insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'people_per_doctor_mohfw', 'mohfw_doctor_population_ratio', 'as answered 29.11.2024', 2024, 811.0, 'lok-sabha-2024-11-29-sq80', 'Lok Sabha Starred Question No. 80, answered 29.11.2024 (MoHFW), Statement', null, '2026-10-16', null, false, 'MoHFW estimate printed as "around 1:811": 13,86,145 allopathic doctors registered with SMCs/NMC as on November 2024, 80% assumed available, plus "around 6.14 lakh AYUSH doctors"; answer calls it better than a "WHO standard of 1:1000" (no WHO document stating that norm was found)');
