insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('IN', 'people_per_doctor_mohfw', 'mohfw_doctor_population_ratio', 'as answered 31.07.2026', 2026, 778.0, 'lok-sabha-2026-07-31-uq2141', 'Lok Sabha Unstarred Question No. 2141, answered 31.07.2026 (MoHFW)', null, '2026-10-16', null, false, 'MoHFW estimate printed as 1:778: 15,35,155 registered allopathic doctors (Indian Medical Register) and 7,51,768 registered AYUSH practitioners, 80% of both assumed available');
